{
  "claims": [
    {
      "claim_text": "WAL mode first appeared in SQLite 3.7.0.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states that beginning with version 3.7.0, a new Write-Ahead Log option is available.",
      "citations": [
        {
          "index": 4,
          "quote": "Beginning with version 3.7.0 (2010-07-21), a new \"Write-Ahead Log\" option (hereafter referred to as \"WAL\") is available."
        }
      ]
    },
    {
      "claim_text": "Because journal_mode=WAL is persistent, simply closing and reopening a WAL database is not enough to change its page size.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] says WAL mode is persistent and the database comes back in WAL mode after reopening. Passage [0] says page size cannot be changed after entering WAL mode, and rollback journal mode is required.",
      "citations": [
        {
          "index": 2,
          "quote": "Unlike the other journaling modes, PRAGMA journal_mode=WAL is persistent. If a process sets WAL mode, then closes and reopens the database, the database will come back in WAL mode."
        },
        {
          "index": 0,
          "quote": "It is not possible to change the page_size after entering WAL mode, either on an empty database or by using VACUUM or by restoring from a backup using the backup API. You must be in a rollback journal mode to change the page size."
        }
      ]
    },
    {
      "claim_text": "You have to switch back to a rollback journal mode first to change the page size.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states that you must be in a rollback journal mode to change the page size.",
      "citations": [
        {
          "index": 0,
          "quote": "You must be in a rollback journal mode to change the page size."
        }
      ]
    },
    {
      "claim_text": "From version 3.7.0 until 3.22.0, reading a WAL-mode database required write access.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] says older versions required write access to read a WAL-mode database, and this was relaxed beginning with 3.22.0. Passage [4] establishes that WAL began with 3.7.0.",
      "citations": [
        {
          "index": 3,
          "quote": "Older versions of SQLite could not read a WAL-mode database that was read-only. In other words, write access was required in order to read a WAL-mode database. This constraint was relaxed beginning with SQLite version 3.22.0 (2018-01-22)."
        },
        {
          "index": 4,
          "quote": "Beginning with version 3.7.0 (2010-07-21), a new \"Write-Ahead Log\" option (hereafter referred to as \"WAL\") is available."
        }
      ]
    },
    {
      "claim_text": "SQLite's default page size is 4096 bytes.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage mentions SQLite's default page size.",
      "citations": []
    },
    {
      "claim_text": "Converting a database to WAL fails if the VFS does not support the necessary shared-memory primitives.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] indicates that conversion to WAL could not be completed if the VFS does not support the necessary shared-memory primitives.",
      "citations": [
        {
          "index": 1,
          "quote": "If the conversion to WAL could not be completed (for example, if the VFS does not support the necessary shared-memory primitives) then the journaling mode will be unchanged..."
        }
      ]
    },
    {
      "claim_text": "In that case, the journal_mode pragma returns an error.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [1] says that on failure the journal_mode pragma does not return an error; it returns the prior journaling mode string, such as 'delete'.",
      "citations": [
        {
          "index": 1,
          "quote": "If the conversion to WAL could not be completed ... then the journaling mode will be unchanged and the string returned from the primitive will be the prior journaling mode (for example \"delete\")."
        }
      ]
    }
  ]
}
